/**
 * Sim events → sound cues (05 §5, §7). Pure and allocation-light: one cue
 * pool reused every frame. Word hits are gathered (the first plays at once,
 * hits landing within 45 ms only add weight, three or more add one
 * "many targets" layer); deaths in a frame fold into one sound per class with
 * a rising pentatonic chime; warnings (a foe winding up on Hỏa Long, a
 * general's telegraph) are P1. Times are seconds on the audio clock.
 * Owner: audio (LANES.md).
 */
import type { EntityRef, FoeId, Grade, HouseId, Material, PlaceableId, SimEvent, TrapId, WordGroup } from "../content/types";
import { CLASS_SETS, GENERAL_SETS, foeSfx, foeVoice, type SoundClass, type SoundId } from "./catalog";

export interface Cue {
  id: SoundId;
  /** Event gain 0–1 on top of the catalog level. */
  gain: number;
  /** Pitch factor (size), 1 = as made. */
  rate: number;
  /** Stereo position −1 … 1 from the listener. */
  pan: number;
  /** Letter step (keys), chain step (kill chime). */
  step: number;
  /** How many things it stands for (gathered hits, deaths, trap victims). */
  count: number;
  /** Variant index: impact a/b/c, word grade 0 normal 1 perfect 2 flash. */
  variant: number;
  material: Material | null;
  /** Start this much later, seconds. */
  delayS: number;
  /** The foe's own sound id (catalog foeSfx) played instead of `id` when its file is loaded; null: none. */
  file: string | null;
  /** True: play only the foe's own file; nothing when it is not loaded (a moment the class sets had no sound for). */
  fileOnly: boolean;
}

/** Where the ears are: the camera's ground focus (metres) and heading (0 looks north, −z). */
export interface Listener {
  x: number;
  z: number;
  yaw: number;
}

/** Half the width of the battlefield that spans the stereo field, metres. */
export const PAN_SPAN_M = 22;
export const MAX_PAN = 0.8;
/** Word hits this close together play as one (05 §7 "gom 30–45 ms"). */
export const GATHER_S = 0.045;
/** Kills this close climb the chime scale (kit AudioCues rule). */
export const CHAIN_S = 1;
export const CHAIN_TOP = 12;
/** Hỏa Long below this share of HP is "low" (05 §7 P1, music surge). */
export const LOW_HP_PCT = 35;
/** A wave start within this long of the warning horn does not blow it again. */
const HORN_DEDUP_S = 8;

export function panFor(x: number, z: number, listener: Listener): number {
  const dx = x - listener.x;
  const dz = z - listener.z;
  // Right of a camera heading `yaw` (0: looking north, right is east).
  const right = dx * Math.cos(listener.yaw) - dz * Math.sin(listener.yaw);
  const pan = right / PAN_SPAN_M;
  return pan < -MAX_PAN ? -MAX_PAN : pan > MAX_PAN ? MAX_PAN : pan;
}

/** Far things are a little quieter, never silent. */
export function distanceGain(x: number, z: number, listener: Listener): number {
  const d = Math.hypot(x - listener.x, z - listener.z);
  const t = Math.min(1, Math.max(0, (d - 8) / 40));
  return 1 - 0.35 * t;
}

const TRAP_SOUNDS: Readonly<Record<TrapId, { arm: SoundId; trigger: SoundId }>> = {
  spikes: { arm: "trap.spikes.arm", trigger: "trap.spikes.trigger" },
  "pine-bomb": { arm: "trap.pine-bomb.arm", trigger: "trap.pine-bomb.trigger" },
  "net-launcher": { arm: "trap.net.arm", trigger: "trap.net.trigger" },
};

const HOUSE_SOUNDS: Readonly<Record<HouseId, { place: SoundId; pulse: SoundId }>> = {
  "herb-hut": { place: "house.herb.place", pulse: "house.herb.pulse" },
};

/** The build sound of anything placed in a slot. */
export function placeSound(item: PlaceableId): SoundId {
  if (item in TRAP_SOUNDS) return TRAP_SOUNDS[item as TrapId].arm;
  if (item in HOUSE_SOUNDS) return HOUSE_SOUNDS[item as HouseId].place;
  return "unit.warden.place";
}

const GRADE_VARIANT: Readonly<Record<Grade, number>> = { sloppy: 0, ok: 0, good: 0, perfect: 1, flash: 2 };

interface DeathFold {
  count: number;
  x: number;
  z: number;
  rate: number;
  material: Material;
  /** The first foe folded in (its own death id stands for the fold). */
  foe: FoeId;
}

/** Hỏa Long's low-HP alarm (05 §7 P1): one alarm on crossing 35 %, then a soft heartbeat while below. */
export class LowHpAlarm {
  private low = false;
  private nextBeat = 0;
  constructor(readonly beatS = 1.4) {}

  update(hpPct: number, now: number): SoundId | null {
    const low = hpPct > 0 && hpPct < LOW_HP_PCT;
    if (low && !this.low) {
      this.low = true;
      this.nextBeat = now + this.beatS;
      return "dragon.low";
    }
    if (!low) {
      this.low = false;
      return null;
    }
    if (now >= this.nextBeat) {
      this.nextBeat = now + this.beatS;
      return "dragon.heartbeat";
    }
    return null;
  }

  get active(): boolean {
    return this.low;
  }
}

export class EventMapper {
  /** Live foes by serial (from `spawn`), so blows and deaths know their class. */
  private readonly foes = new Map<number, FoeId>();
  private readonly generals = new Set<number>();
  private readonly wordGroups = new Map<number, WordGroup>();
  private readonly pool: Cue[] = [];
  private readonly out: Cue[] = [];
  private readonly deaths = new Map<SoundClass, DeathFold>();
  private window = { start: -1e9, count: 0, multi: false };
  private chain = { step: 0, last: -1e9 };
  private impactTurn = 0;
  private lastHorn = -1e9;
  private rageFull = false;
  private warningUntil = -1e9;
  /** Run flow the music reads. */
  phase: string = "prep";
  wave = 0;
  waves = 10;

  /** A general alive on the field (music adds its layer). */
  get generalsAlive(): number {
    return this.generals.size;
  }

  /** A general's telegraph is open: warning duck, no pronunciation (01 §6.4). */
  warningActive(now: number): boolean {
    return now < this.warningUntil;
  }

  /** Forgets the run (new stage, restart). */
  reset(): void {
    this.foes.clear();
    this.generals.clear();
    this.wordGroups.clear();
    this.window = { start: -1e9, count: 0, multi: false };
    this.chain = { step: 0, last: -1e9 };
    this.rageFull = false;
    this.warningUntil = -1e9;
    this.phase = "prep";
    this.wave = 0;
  }

  /** The cues for one frame's events; the array and its cues are reused by the next call. */
  map(events: readonly SimEvent[], now: number, listener: Listener): readonly Cue[] {
    this.out.length = 0;
    this.deaths.clear();
    for (const event of events) this.one(event, now, listener);
    this.foldDeaths(now, listener);
    const w = this.window;
    if (w.count >= 3 && !w.multi && now - w.start < GATHER_S) {
      w.multi = true;
      this.push("impact.multi", { gain: Math.min(1, 0.55 + Math.log2(w.count) * 0.15), count: w.count });
    }
    return this.out;
  }

  private one(event: SimEvent, now: number, listener: Listener): void {
    switch (event.type) {
      case "phase":
        this.phase = event.phase;
        this.wave = event.wave;
        if (event.phase === "warning") {
          this.lastHorn = now;
          this.push("wave.horn");
        }
        return;
      case "wave-start":
        this.wave = event.wave;
        this.waves = event.waves;
        this.phase = "wave";
        if (now - this.lastHorn > HORN_DEDUP_S) {
          this.lastHorn = now;
          this.push("wave.horn");
        }
        return;
      case "wave-end":
        this.push("wave.clear");
        return;
      case "victory":
        this.phase = "victory";
        this.push("stinger.victory");
        return;
      case "defeat":
        this.phase = "defeat";
        this.push("dragon.down");
        this.push("stinger.defeat", { delayS: 0.5 });
        return;
      case "spawn": {
        this.foes.set(event.enemy.serial, event.foe);
        const voice = foeVoice(event.foe);
        if (!voice) return;
        if (voice.general) {
          this.generals.add(event.enemy.serial);
          const set = GENERAL_SETS[event.foe];
          if (set) this.at(set.horn, event.x, event.z, listener);
          return;
        }
        this.at(CLASS_SETS[voice.cls].spawn, event.x, event.z, listener, { rate: voice.rate, file: foeSfx(event.foe)?.spawn ?? null });
        return;
      }
      case "attack": {
        if (event.source.kind !== "enemy") return;
        const voice = this.voiceOf(event.source);
        if (!voice) return;
        const onDragon = event.target.kind === "hero" || event.target.kind === "guide";
        if (event.stage === "windup") {
          if (onDragon) this.push("warn.strike", { pan: panFor(event.x, event.z, listener) });
          this.at(CLASS_SETS[voice.cls].windup, event.x, event.z, listener, { rate: voice.rate });
          return;
        }
        const general = voice.general ? GENERAL_SETS[this.foes.get(event.source.serial) ?? ""] : undefined;
        const set = CLASS_SETS[voice.cls];
        const id = general ? general.attack : voice.attack === "ranged" ? set.shoot : voice.attack === "charge" ? set.charge : set.attack;
        this.at(id, event.x, event.z, listener, { rate: voice.rate, file: foeSfx(this.foes.get(event.source.serial) ?? "")?.attack ?? null });
        return;
      }
      case "telegraph": {
        if (event.owner !== "enemy" || event.source.kind !== "enemy") return;
        const foe = this.foes.get(event.source.serial);
        const set = foe ? GENERAL_SETS[foe] : undefined;
        if (!set) return;
        this.warningUntil = Math.max(this.warningUntil, now + event.durationMs / 1000);
        this.push("warn.telegraph", { pan: panFor(event.x, event.z, listener) });
        this.at(set.skill, event.x, event.z, listener, { delayS: Math.min(2, event.durationMs / 1000) });
        return;
      }
      case "hit":
        this.hit(event, now, listener);
        return;
      case "death":
        this.death(event, now, listener);
        return;
      case "trap-trigger": {
        const sounds = TRAP_SOUNDS[event.trap];
        if (sounds) this.at(sounds.trigger, event.x, event.z, listener, { count: event.count, gain: Math.min(1, 0.7 + Math.log2(1 + event.count) * 0.12) });
        return;
      }
      case "word-assigned":
        this.wordGroups.set(event.word, event.group);
        return;
      case "word-released":
        this.wordGroups.delete(event.word);
        return;
      case "word-progress":
        this.key(event.key, event.typed);
        return;
      case "word-complete": {
        this.push("type.word", { variant: GRADE_VARIANT[event.grade] });
        if (event.target !== null && event.target.kind === "enemy") this.push("fire.cast", { pan: 0 });
        if (event.scored && this.wordGroups.get(event.word) === "new") this.push("learn.new");
        return;
      }
      case "gold":
        if (event.delta > 0 && (event.reason === "review-card" || event.reason === "learn-ahead")) this.push("learn.right");
        else if (event.reason === "wave-end" && event.delta > 0) this.push("ui.gold");
        return;
      case "rage":
        if (event.full && !this.rageFull) this.push("dragon.rage");
        this.rageFull = event.full;
        return;
      case "skill":
        this.skill(event, listener);
        return;
      case "hero-level":
        this.push("dragon.level");
        return;
      case "built":
        this.push(placeSound(event.item));
        return;
      case "upgraded":
      case "bought":
        this.push("ui.confirm");
        return;
      case "sold":
        this.push("ui.gold");
        return;
      case "consumable":
        this.push("dragon.potion");
        return;
      case "rejected":
        this.push("ui.deny");
        return;
      case "unit-down":
        this.at("unit.warden.down", event.x, event.z, listener);
        return;
      case "unit-up":
        this.at("unit.warden.place", event.x, event.z, listener, { gain: 0.6 });
        return;
      case "house-pulse": {
        const sounds = HOUSE_SOUNDS[event.house];
        if (sounds) this.at(sounds.pulse, event.x, event.z, listener);
        return;
      }
      case "heal":
        // A heal beat: the herb pulse, quiet (its 300 ms gap keeps several allies to one sound).
        if (event.source.kind === "house") this.at("house.herb.pulse", event.x, event.z, listener, { gain: 0.35 });
        return;
      case "aura": {
        const foe = this.foes.get(event.enemy.serial);
        const set = foe ? GENERAL_SETS[foe] : undefined;
        if (!set) return;
        this.push(event.on ? set.aura : "general.aura.break");
        return;
      }
      case "move":
      case "status":
      case "grade":
        return;
    }
  }

  private key(result: string, typed: number): void {
    switch (result) {
      case "lock":
      case "advance":
      case "pair":
      case "done":
        this.push("type.key", { step: Math.max(0, typed - 1) });
        return;
      case "switch":
        this.push("type.switch");
        return;
      case "back":
        this.push("type.back");
        return;
      case "wrong":
      case "stray":
        this.push("type.miss");
        return;
      default:
        // "asleep": the router is asleep (phase, hidden words); stay quiet.
        return;
    }
  }

  private hit(event: Extract<SimEvent, { type: "hit" }>, now: number, listener: Listener): void {
    const target = event.target;
    if (target.kind === "hero") {
      // Héo lan (source "hero", every 2 s while foes stand near) is quieter than a blow but grows with the beat:
      // in the last waves it takes 60–110 HP a beat and was nearly silent at 0.25 (test pass 27/10).
      const seep = event.source.kind === "hero";
      this.push("dragon.hurt", { gain: seep ? Math.min(0.85, 0.4 + event.amount / 150) : Math.min(1, 0.55 + event.amount / 120) });
      return;
    }
    if (target.kind === "unit" || target.kind === "trap" || target.kind === "house") {
      this.at("unit.hit", event.x, event.z, listener, { rate: target.kind === "unit" ? 1 : 0.8 });
      return;
    }
    if (target.kind !== "enemy") return;
    if (event.source.kind === "hero" && event.damageType === "word") {
      const w = this.window;
      if (now - w.start < GATHER_S) {
        w.count += 1;
        return;
      }
      this.window = { start: now, count: 1, multi: false };
      const big = event.tier >= 3 || event.grade === "flash" || event.grade === "perfect";
      const variant = big ? 2 : this.impactTurn++ % 2;
      const id: SoundId = variant === 2 ? "fire.impact.c" : variant === 1 ? "fire.impact.b" : "fire.impact.a";
      this.at(id, event.x, event.z, listener, { variant, gain: big ? 1 : 0.85 });
      // The foe's own hit voice, once its file exists (the class sets had none under a word's fire impact).
      const voice = this.voiceOf(target);
      const own = foeSfx(this.foes.get(target.serial) ?? "")?.hit ?? null;
      if (voice && own) this.at(CLASS_SETS[voice.cls].hit, event.x, event.z, listener, { rate: voice.rate, material: voice.material, gain: 0.6, file: own, fileOnly: true });
      return;
    }
    if (event.source.kind === "unit") {
      const voice = this.voiceOf(target);
      if (voice) this.at(CLASS_SETS[voice.cls].hit, event.x, event.z, listener, { rate: voice.rate, material: voice.material, gain: 0.6, file: foeSfx(this.foes.get(target.serial) ?? "")?.hit ?? null });
    }
  }

  private death(event: Extract<SimEvent, { type: "death" }>, now: number, listener: Listener): void {
    // Generals sound at once; others fold per class at the end of the frame (foldDeaths).
    this.foes.delete(event.enemy.serial);
    const voice = foeVoice(event.foe);
    if (this.generals.delete(event.enemy.serial) || voice?.general) {
      const set = GENERAL_SETS[event.foe];
      if (set) this.at(set.death, event.x, event.z, listener);
      this.chime(now);
      return;
    }
    if (!voice) return;
    const fold = this.deaths.get(voice.cls);
    if (fold) fold.count += 1;
    else this.deaths.set(voice.cls, { count: 1, x: event.x, z: event.z, rate: voice.rate, material: event.material, foe: event.foe });
  }

  /** One death sound per class per frame, louder as √N (05 §5 "một vụ nổ cỡ √N"), and one chime. */
  private foldDeaths(now: number, listener: Listener): void {
    if (this.deaths.size === 0) return;
    for (const [cls, fold] of this.deaths) {
      this.at(CLASS_SETS[cls].death, fold.x, fold.z, listener, {
        file: foeSfx(fold.foe)?.death ?? null,
        rate: fold.rate,
        material: fold.material,
        count: fold.count,
        gain: Math.min(1, 0.75 + Math.sqrt(fold.count - 1) * 0.1),
      });
    }
    this.chime(now);
  }

  private chime(now: number): void {
    const c = this.chain;
    c.step = now - c.last < CHAIN_S ? Math.min(CHAIN_TOP, c.step + 1) : 0;
    c.last = now;
    this.push("kill.chime", { step: c.step });
  }

  private skill(event: Extract<SimEvent, { type: "skill" }>, listener: Listener): void {
    if (event.stage === "ready") {
      this.push("dragon.skill-ready");
      return;
    }
    if (event.stage === "cast") {
      const id: SoundId | null =
        event.skill === "breath" ? "dragon.breath" : event.skill === "skyfire" ? "dragon.skyfire.cast" : event.skill === "roar" ? "dragon.roar" : event.skill === "inferno" ? "dragon.inferno" : null;
      if (id) this.push(id);
      return;
    }
    if (event.stage === "impact" && (event.skill === "skyfire" || event.skill === "inferno")) {
      this.at("dragon.skyfire.impact", event.x, event.z, listener, { gain: event.skill === "inferno" ? 1 : 0.9 });
    }
  }

  private voiceOf(ref: EntityRef) {
    if (ref.kind !== "enemy") return null;
    const foe = this.foes.get(ref.serial);
    return foe ? foeVoice(foe) : null;
  }

  private at(id: SoundId, x: number, z: number, listener: Listener, opts: Partial<Omit<Cue, "id">> = {}): void {
    this.push(id, { pan: panFor(x, z, listener), ...opts, gain: (opts.gain ?? 1) * distanceGain(x, z, listener) });
  }

  private push(id: SoundId, opts: Partial<Omit<Cue, "id">> = {}): void {
    const index = this.out.length;
    let cue = this.pool[index];
    if (!cue) {
      cue = { id, gain: 1, rate: 1, pan: 0, step: 0, count: 1, variant: 0, material: null, delayS: 0, file: null, fileOnly: false };
      this.pool.push(cue);
    }
    cue.id = id;
    cue.gain = opts.gain ?? 1;
    cue.rate = opts.rate ?? 1;
    cue.pan = opts.pan ?? 0;
    cue.step = opts.step ?? 0;
    cue.count = opts.count ?? 1;
    cue.variant = opts.variant ?? 0;
    cue.material = opts.material ?? null;
    cue.delayS = opts.delayS ?? 0;
    cue.file = opts.file ?? null;
    cue.fileOnly = opts.fileOnly ?? false;
    this.out.push(cue);
  }
}

dh-vfx:src/audio/index.ts:
/**
 * Game audio (05 §7): a Presenter that hears the sim's events and plays them
 * on 12 buses (master, music, ui, typing, dragon, enemies, traps, units,
 * ambience, voice, stingers, learning). Class sound sets, not species; a
 * limiter so 200 foes never clip; pronunciation and the learning frame's
 * sounds always on top (every other bus dips while a word is spoken); a
 * two-layer procedural forest-folk score that follows the run. M0a has no
 * files: every sound is a WebAudio synth behind a SoundBank, and the owner's
 * files (public/assets/dragon-hold/audio/, never in Git) replace them later.
 * Owner: audio (LANES.md).
 */
import type { FrameInfo, Presenter, Quality } from "../app/contracts";
import type { SimEvent } from "../content/types";
import { PRONUNCIATION_EVENT } from "../kit/speech";
import { uToM } from "../sim/fixed";
import type { World } from "../sim/world";
import { FileBank, LayeredBank, SynthBank, type SoundBank } from "./bank";
import { CHILD_BUSES, CLASS_SETS, foeSfx, foeVoice, type SoundClass } from "./catalog";
import { AudioEngine } from "./engine";
import { VOICE_CAP } from "./limiter";
import { EventMapper, LowHpAlarm, panFor, type Listener } from "./map-events";
import { AudioMix, DEFAULT_VOLUMES, NO_DUCK, type AudioVolumes, type DuckState } from "./mix";
import { Mixer } from "./mixer";
import { MusicDirector } from "./music";
import { musicTargets } from "./music-plan";

export type UiSound = "select" | "confirm" | "deny" | "gold";
export type LearningSound = "new" | "right" | "wrong";

export interface AudioOptions {
  /** Device tier: voice cap 16 / 24 / 32 / 32 (05 §8). */
  readonly quality?: Quality;
  /** Settings volumes 0–1 (06 §3 defaults). */
  readonly volumes?: Partial<AudioVolumes>;
  /** Load the owner's files from /assets/dragon-hold/audio/manifest.json (M0a: false, all synth, no fetch). */
  readonly files?: boolean;
  /** Resume audio on the first key or pointer press on `window` (default true). */
  readonly autoUnlock?: boolean;
  /** Where the pronunciation event comes from (kit speech); default `window`. */
  readonly events?: EventTarget | null;
  /** Make the context yourself (tests, a shared context). */
  readonly createContext?: () => AudioContext;
  readonly random?: () => number;
}

export interface AudioStats {
  readonly unlocked: boolean;
  readonly bank: string;
  readonly voices: number;
  readonly peakVoices: number;
  readonly admitted: number;
  readonly stolen: number;
  readonly rejected: Readonly<Record<string, number>>;
  readonly ducks: Readonly<Record<string, number>>;
  readonly music: Readonly<Record<string, number>>;
}

export interface GameAudio extends Presenter {
  /** Resumes (or creates) the AudioContext; call from a user gesture. */
  unlock(): void;
  readonly unlocked: boolean;
  setMuted(muted: boolean): void;
  setVolumes(volumes: Partial<AudioVolumes>): void;
  /** Focus lost or menu open: world and music low-passed, effects down (06 §2). */
  setPaused(paused: boolean): void;
  setQuality(quality: Quality): void;
  /** The portal plays its own music (kit learning bridge onSharedMusic): game music goes silent. */
  setSharedMusic(playing: boolean): void;
  /** A Bạch Long or narrator line is playing (06 §6): music, ambience, enemies dip. */
  setDialogue(active: boolean): void;
  /** Settings voice boost 1–3: effects dip deeper while a word is spoken (kit BusMix). */
  setPronunciationBoost(boost: number): void;
  /** Camera ground focus (metres) and heading (radians, 0 looks north) for stereo placement. */
  setListener(xM: number, zM: number, yaw: number): void;
  /** UI sounds for DOM panels (shop strip, placement, menus). */
  ui(sound: UiSound): void;
  /** Learning frame sounds (Thẻ Ôn, Học trước); never ducked. */
  learning(sound: LearningSound): void;
  /** Pronunciation should wait (general or boss warning open, dialogue): use in kit setSpeechGate (01 §6.4). */
  speechBlocked(): boolean;
  /** A new run on the same audio (restart, next stage): forgets foes, words, alarms; stops voices and music. */
  resetRun(): void;
  stats(): AudioStats;
}

const now = (): number => performance.now() / 1000;

export function createAudio(options: AudioOptions = {}): GameAudio {
  const random = options.random ?? Math.random;
  const mix = new AudioMix();
  const mapper = new EventMapper();
  let alarm = new LowHpAlarm();
  const synthBank = new SynthBank(random);
  const fileBank = options.files ? new FileBank() : null;
  const bank: SoundBank = fileBank ? new LayeredBank(fileBank, synthBank) : synthBank;
  const listener: Listener = { x: 0, z: 0, yaw: 0 };
  const events = options.events !== undefined ? options.events : typeof window === "undefined" ? null : window;
  let volumes: AudioVolumes = { ...DEFAULT_VOLUMES, ...options.volumes };
  let quality: Quality = options.quality ?? "high";
  let ctx: AudioContext | null = null;
  let mixer: Mixer | null = null;
  let engine: AudioEngine | null = null;
  let music: MusicDirector | null = null;
  let muted = false;
  let paused = false;
  let sharedMusic = false;
  let dialogue = false;
  let pronouncing = false;
  let ducks: DuckState = NO_DUCK;
  let nextBird = 0;
  let disposed = false;

  const onSpeech = (event: Event): void => {
    pronouncing = (event as CustomEvent<{ active?: boolean }>).detail?.active === true;
  };
  events?.addEventListener(PRONUNCIATION_EVENT, onSpeech);

  const gesture = (): void => audio.unlock();
  const autoUnlock = (options.autoUnlock ?? true) && typeof window !== "undefined";
  if (autoUnlock) {
    window.addEventListener("pointerdown", gesture, { capture: true });
    window.addEventListener("keydown", gesture, { capture: true });
  }
  const dropGesture = (): void => {
    if (!autoUnlock) return;
    window.removeEventListener("pointerdown", gesture, { capture: true });
    window.removeEventListener("keydown", gesture, { capture: true });
  };

  const counts = new Map<SoundClass, { n: number; x: number; z: number; lead: string; kinds: Map<string, number> }>();

  /** Crowd loops by class and the forest beds, from the world (05 §7.1). */
  function beds(world: World): void {
    if (!engine) return;
    for (const value of counts.values()) value.n = 0;
    for (const enemy of world.enemies.list) {
      if (!enemy.alive || enemy.freed) continue;
      const voice = foeVoice(enemy.foe);
      if (!voice) continue;
      let entry = counts.get(voice.cls);
      if (!entry) {
        entry = { n: 0, x: 0, z: 0, lead: "", kinds: new Map() };
        counts.set(voice.cls, entry);
      }
      if (entry.n === 0) {
        entry.x = 0;
        entry.z = 0;
        entry.lead = "";
        entry.kinds.clear();
      }
      entry.n += 1;
      const kind = (entry.kinds.get(enemy.foe) ?? 0) + 1;
      entry.kinds.set(enemy.foe, kind);
      if (entry.lead === "" || kind > (entry.kinds.get(entry.lead) ?? 0)) entry.lead = enemy.foe;
      entry.x += uToM(enemy.x);
      entry.z += uToM(enemy.z);
    }
    for (const cls of Object.keys(CLASS_SETS) as SoundClass[]) {
      const entry = counts.get(cls);
      const n = entry?.n ?? 0;
      const level = n === 0 ? 0 : Math.min(1, 0.3 + 0.7 * Math.sqrt(n / 40));
      const pan = entry && n > 0 ? panFor(entry.x / n, entry.z / n, listener) * 0.6 : 0;
      engine.bed(CLASS_SETS[cls].march, level, pan, 0.4, entry && n > 0 ? (foeSfx(entry.lead)?.move ?? null) : null);
    }
    const battle = world.phase === "wave";
    engine.bed("amb.forest", battle ? 0.65 : 1);
    engine.bed("amb.river", 1, -0.2);
    const t = now();
    if (!battle && t > nextBird) {
      nextBird = t + 4 + random() * 7;
      if (world.phase === "prep" || world.phase === "break") engine.play({ id: "amb.bird", pan: random() * 1.2 - 0.6, gain: 0.6 + random() * 0.4 });
    }
  }

  const audio: GameAudio = {
    get unlocked() {
      return ctx !== null && ctx.state !== "closed";
    },

    unlock() {
      if (disposed) return;
      if (ctx) {
        if (ctx.state === "suspended") void ctx.resume();
        return;
      }
      if (typeof AudioContext === "undefined" && !options.createContext) return;
      ctx = options.createContext ? options.createContext() : new AudioContext({ latencyHint: "interactive" });
      mixer = new Mixer(ctx, mix, volumes);
      mixer.setMuted(muted);
      mixer.setPaused(paused);
      engine = new AudioEngine(mixer, bank, { maxVoices: VOICE_CAP[quality] }, random);
      music = new MusicDirector(ctx, mixer.input("music"), bank, synthBank.noiseFor(ctx), undefined, random);
      engine.rootHz = music.rootHz;
      if (ctx.state === "suspended") void ctx.resume();
      if (fileBank) void fileBank.load(ctx);
      dropGesture();
    },

    onEvents(batch: readonly SimEvent[], _world: World) {
      const cues = mapper.map(batch, now(), listener);
      if (music && (mapper.phase === "victory" || mapper.phase === "defeat") && batch.some((e) => e.type === "victory" || e.type === "defeat")) music.stop(1.5);
      if (!engine) return;
      for (const cue of cues) engine.play(cue);
    },

    frame(world: World, _info: FrameInfo) {
      if (!engine || !mixer || !music || !ctx) return;
      const heroPct = world.hero.hpMax > 0 ? (world.hero.hp * 100) / world.hero.hpMax : 100;
      const alarmCue = world.phase === "wave" ? alarm.update(heroPct, now()) : alarm.update(100, now());
      if (alarmCue) engine.play({ id: alarmCue });

      music.update(
        ctx.currentTime,
        musicTargets({ phase: world.phase, wave: world.wave, waves: mapper.waves, heroPct, live: world.enemies.live, generals: mapper.generalsAlive, sharedMusic }),
      );

      const state: DuckState = { pronunciation: pronouncing, dialogue, warning: mapper.warningActive(now()) };
      for (const bus of CHILD_BUSES) {
        const target = mix.target(bus, state, mixer.duckOf(bus), ducks);
        mixer.setDuck(bus, target.duck, target.rampS);
      }
      ducks = state;
      beds(world);
    },

    setMuted(value) {
      muted = value;
      mixer?.setMuted(value);
    },

    setVolumes(next) {
      volumes = { ...volumes, ...next };
      mixer?.setVolumes(volumes);
    },

    setPaused(value) {
      paused = value;
      mixer?.setPaused(value);
    },

    setQuality(value) {
      quality = value;
      engine?.limiter.setMaxVoices(VOICE_CAP[value]);
    },

    setSharedMusic(playing) {
      sharedMusic = playing;
    },

    setDialogue(active) {
      dialogue = active;
    },

    setPronunciationBoost(boost) {
      mix.setPronunciationBoost(boost);
    },

    setListener(xM, zM, yaw) {
      listener.x = xM;
      listener.z = zM;
      listener.yaw = yaw;
    },

    ui(sound) {
      engine?.play({ id: `ui.${sound}` });
    },

    learning(sound) {
      engine?.play({ id: `learn.${sound}` });
    },

    speechBlocked() {
      return dialogue || mapper.warningActive(now());
    },

    resetRun() {
      mapper.reset();
      alarm = new LowHpAlarm();
      music?.stop(0.6);
      engine?.stopAll();
    },

    stats(): AudioStats {
      const limiter = engine?.limiter.stats;
      return {
        unlocked: audio.unlocked,
        bank: bank.name,
        voices: engine?.activeVoices() ?? 0,
        peakVoices: limiter?.peak ?? 0,
        admitted: limiter?.admitted ?? 0,
        stolen: limiter?.stolen ?? 0,
        rejected: { ...(limiter?.rejected ?? {}) },
        ducks: Object.fromEntries(CHILD_BUSES.map((bus) => [bus, mixer?.duckOf(bus) ?? 1])),
        music: { ...(music?.levels() ?? {}) },
      };
    },

    dispose() {
      if (disposed) return;
      disposed = true;
      dropGesture();
      events?.removeEventListener(PRONUNCIATION_EVENT, onSpeech);
      engine?.stopAll();
      music?.dispose();
      mixer?.dispose();
      if (ctx && !options.createContext) void ctx.close();
      ctx = null;
      engine = null;
      music = null;
      mixer = null;
    },
  };
  return audio;
}

export { BUSES, SOUNDS, SOUND_IDS, type Bus, type SoundId } from "./catalog";
export { DEFAULT_VOLUMES, type AudioVolumes } from "./mix";
export { FileBank, LayeredBank, SynthBank, type AudioManifest, type SoundBank } from "./bank";

dh-vfx:src/audio/engine.ts:
/**
 * Plays cues: limiter first (voice cap, rate limits, stealing), then one
 * voice = gain → pan → bus, built by the bank at the audio clock. Impacts and
 * world sounds vary a little (pitch ±4 %, ±1.5 dB, 0–12 ms, 05 §7); typing,
 * UI and learning stay exact and immediate. Looping beds (ambience, crowd)
 * run on their own gain, never through the limiter.
 * Owner: audio (LANES.md).
 */
import type { SoundBank } from "./bank";
import { SOUNDS, type SoundId } from "./catalog";
import { VoiceLimiter, type LimiterRules } from "./limiter";
import type { Cue } from "./map-events";
import { dbToGain } from "./mix";
import { ramp, type Mixer } from "./mixer";
import { DEFAULT_PARAMS, type SoundParams } from "./synth";

/** A stolen voice fades this fast (no click). */
const STEAL_FADE_S = 0.025;

export type CueLike = Pick<Cue, "id"> & Partial<Omit<Cue, "id">>;

interface LiveVoice {
  readonly gain: GainNode;
  readonly end: number;
}

interface Bed {
  readonly gain: GainNode;
  readonly pan: StereoPannerNode;
  readonly source: AudioBufferSourceNode;
  level: number;
  panValue: number;
}

export class AudioEngine {
  readonly limiter: VoiceLimiter;
  private readonly voices = new Map<number, LiveVoice>();
  private readonly beds = new Map<SoundId, Bed>();
  private sweepAt = 0;
  /** Chime root (Hz) from the music, so notes sit in its key. */
  rootHz = DEFAULT_PARAMS.rootHz;

  constructor(
    readonly mixer: Mixer,
    readonly bank: SoundBank,
    rules: Partial<LimiterRules> = {},
    private readonly random: () => number = Math.random,
  ) {
    this.limiter = new VoiceLimiter(rules);
  }

  get ctx(): BaseAudioContext {
    return this.mixer.ctx;
  }

  /** Plays one cue now (plus its delay); false when the limiter or the bank said no. */
  play(cue: CueLike, at = this.ctx.currentTime): boolean {
    const def = SOUNDS[cue.id];
    // A foe's own file (catalog foeSfx) plays in its class sound's place, with the class sound's bus, priority and gap.
    const file = cue.file && this.bank.hasFoe?.(cue.file) ? cue.file : null;
    if (def.loop || (file === null && (cue.fileOnly || !this.bank.has(cue.id)))) return false;
    const vary = def.vary;
    const rate = (cue.rate ?? 1) * (vary ? 0.96 + this.random() * 0.08 : 1);
    const jitterDb = vary ? (this.random() * 2 - 1) * 1.5 : 0;
    const when = at + (cue.delayS ?? 0) + (vary ? this.random() * 0.012 : 0);
    const admission = this.limiter.admit({
      sound: cue.id,
      priority: def.priority,
      lengthS: def.lengthMs / 1000 / rate + (cue.delayS ?? 0),
      gapS: def.gapMs / 1000,
      ...(def.group ? { group: def.group } : {}),
      now: at,
    });
    if (!admission.ok) return false;
    for (const id of admission.steal) this.fade(id, at);

    const ctx = this.ctx;
    const gain = ctx.createGain();
    gain.gain.value = dbToGain(def.gainDb + jitterDb) * Math.max(0, Math.min(1.5, cue.gain ?? 1));
    const pan = ctx.createStereoPanner();
    pan.pan.value = Math.max(-1, Math.min(1, cue.pan ?? 0));
    gain.connect(pan).connect(this.mixer.input(def.bus));
    const params: SoundParams = {
      rate,
      step: cue.step ?? 0,
      count: cue.count ?? 1,
      variant: cue.variant ?? 0,
      material: cue.material ?? null,
      rootHz: this.rootHz,
    };
    const length = file !== null ? (this.bank.playFoe?.(ctx, file, gain, when, params) ?? 0) : this.bank.play(ctx, cue.id, gain, when, params);
    if (length <= 0) {
      this.limiter.release(admission.voice);
      gain.disconnect();
      return false;
    }
    // Hold the voice for what plays (a short synth placeholder or the file), not the catalog's target length.
    this.limiter.settle(admission.voice, when + length);
    this.voices.set(admission.voice, { gain, end: when + length });
    if (at > this.sweepAt) this.sweep(at);
    return true;
  }

  /** Starts (once) and levels a looping bed; level 0 keeps it running silently. */
  bed(id: SoundId, level: number, pan = 0, rampS = 0.4, file: string | null = null): void {
    const def = SOUNDS[id];
    if (!def.loop) return;
    let bed = this.beds.get(id);
    const now = this.ctx.currentTime;
    if (!bed) {
      if (level <= 0) return;
      // The leading foe's own move loop (catalog foeSfx), when loaded, in the class bed's place.
      const buffer = (file !== null ? this.bank.loopFoe?.(this.ctx, file) : null) ?? this.bank.loop(this.ctx, id);
      if (!buffer) return;
      const source = this.ctx.createBufferSource();
      source.buffer = buffer;
      source.loop = true;
      const gain = this.ctx.createGain();
      gain.gain.value = 0;
      const panner = this.ctx.createStereoPanner();
      source.connect(gain).connect(panner).connect(this.mixer.input(def.bus));
      // Start somewhere in the loop so beds of the same length do not phase together.
      source.start(now, this.random() * buffer.duration);
      bed = { gain, pan: panner, source, level: 0, panValue: 0 };
      this.beds.set(id, bed);
    }
    // Levels and pans move in small steps so a changing crowd does not flood the param timeline.
    const target = dbToGain(def.gainDb) * Math.round(Math.max(0, Math.min(1, level)) * 50) / 50;
    if (Math.abs(target - bed.level) > 1e-4) {
      bed.level = target;
      ramp(bed.gain.gain, target, now, rampS);
    }
    const panTarget = Math.round(Math.max(-0.6, Math.min(0.6, pan)) * 20) / 20;
    if (panTarget !== bed.panValue) {
      bed.panValue = panTarget;
      bed.pan.pan.setTargetAtTime(panTarget, now, 0.3);
    }
  }

  /** Voices sounding now (for stats). */
  activeVoices(): number {
    return this.limiter.active(this.ctx.currentTime);
  }

  stopAll(): void {
    const now = this.ctx.currentTime;
    for (const id of [...this.voices.keys()]) this.fade(id, now);
    for (const bed of this.beds.values()) {
      ramp(bed.gain.gain, 0, now, 0.2);
      bed.source.stop(now + 0.3);
    }
    this.beds.clear();
    this.limiter.clear();
  }

  private fade(id: number, now: number): void {
    const voice = this.voices.get(id);
    if (!voice) return;
    this.voices.delete(id);
    voice.gain.gain.cancelScheduledValues(now);
    voice.gain.gain.setValueAtTime(voice.gain.gain.value, now);
    voice.gain.gain.linearRampToValueAtTime(0, now + STEAL_FADE_S);
  }

  /** Forgets finished voices (their nodes end on their own). */
  private sweep(now: number): void {
    this.sweepAt = now + 1;
    for (const [id, voice] of this.voices) if (voice.end < now) this.voices.delete(id);
  }
}

